<?php $items=sc_cart();$totals=sc_totals($items); ?>
<section class="sc-store"><span class="sc-kicker">YOUR EVERYDAY SUPPORT</span><h1>Your cart.</h1><?php sc_flash(); ?><?php if($GLOBALS['sc_error']): ?><div class="alert alert-danger" role="alert"><?= sc_e($GLOBALS['sc_error']) ?></div><?php endif; ?>
<?php if(!$items): ?><div class="sc-panel"><p>Your cart is empty.</p><a class="sc-buy" href="<?= sc_url('products') ?>">Explore the collection ↗</a></div><?php else: ?><form method="post"><?= sc_token() ?><input type="hidden" name="sc_action" value="cart_update"><div class="sc-cart-layout"><div><?php foreach($items as $p): ?><div class="sc-cart-row"><img src="<?= sc_e(sc_image($p)) ?>" alt="<?= sc_e($p['product_name']) ?>"><div><a href="<?= sc_url('products/'.rawurlencode($p['category_slug']).'/'.rawurlencode($p['slug'])) ?>"><?= sc_e($p['product_name']) ?></a><p><?= sc_money($p['unit_cents']) ?> each</p><label>Quantity (0 to remove)<input aria-label="Quantity for <?= sc_e($p['product_name']) ?>" type="number" name="quantity[<?= (int)$p['id'] ?>]" min="0" max="20" value="<?= $p['quantity'] ?>"></label></div><strong><?= sc_money($p['line_cents']) ?></strong></div><?php endforeach; ?><button class="sc-buy" type="submit">Update cart</button></div><aside class="sc-panel"><h2>Order summary</h2><p>Items <strong><?= sc_money($totals['subtotal']) ?></strong></p><p>Tax estimate (Odisha) <strong><?= sc_money($totals['tax']) ?></strong></p><p>Shipping <strong>₹0.00</strong></p><hr><p>Total <strong><?= sc_money($totals['total']) ?></strong></p><small>Final tax is calculated from your delivery state at checkout.</small><a class="sc-buy" href="<?= sc_url('checkout') ?>">Continue to checkout ↗</a><a href="<?= sc_url('products') ?>">Continue shopping</a></aside></div></form><?php endif; ?></section>
